select.where:
and disease_name like concat('%', #{diseaseName},'%')
and disease_id != #{noDiseaseId}
and disease_name = #{diseaseName}
and dept_id = #{deptId}
and is_deleted = #{isDeleted}
and sort_num = #{sortNum}
and is_deleted = '0'

mapper.select:
select d.dept_id, d.parent_id,d.dept_name,rd.disease_id,rd.disease_name,ri.id as research_id,ri.project_name, ri.stage,ri.research_status
from sys_dept d
INNER JOIN  research_diseases rd on rd.dept_id=d.dept_id and rd.is_deleted='0'
INNER join research_info ri on ri.disease_type_id=rd.disease_id and ri.del_flag='0'

    INNER JOIN (
    select user_id,research_id from research_user_role where user_id=#{userId} GROUP BY user_id,research_id
    ) ru on ri.id=ru.research_id


     and ri.research_status = #{researchStatus}
     and ri.project_name like concat('%', #{projectName}, '%')
     and ri.id = #{id}
     and rd.dept_id = #{deptId} and ri.dept_id = #{deptId} and d.dept_id = #{deptId}
    and ri.research_status != #{notResearchStatus}
    and rd.disease_name like concat('%', #{diseasesName}, '%')
    and d.del_flag='0' and d.dept_type = '2'


${params.dataScope}
order by d.parent_id, d.order_num

select d.dept_id,d.dept_name,rd.disease_id,rd.disease_name,ri.id as research_id,ri.project_name,
       ri.stage,ri.research_status,ri.create_by,d.order_num,ri.is_follow_rate
from sys_dept d
LEFT JOIN  research_diseases rd on rd.dept_id=d.dept_id and rd.is_deleted='0'
LEFT join research_info ri on ri.disease_type_id=rd.disease_id and ri.del_flag='0'

    INNER JOIN (
    select user_id,research_id from research_user_role where user_id=#{userId} GROUP BY user_id,research_id
    ) ru on ri.id=ru.research_id


     and ri.project_name like concat('%', #{projectName}, '%')
     and ri.id = #{id}
     and ri.research_status = #{researchStatus}
     and rd.dept_id = #{deptId}  and d.dept_id = #{deptId}
    and d.del_flag='0' and d.dept_type = '2' and d.status=0 AND rd.disease_id is not null


${params.dataScope}
order by d.parent_id, d.order_num

select d.dept_id,d.dept_name,rd.disease_id,rd.disease_name from sys_dept d
left join research_diseases rd on rd.dept_id=d.dept_id and rd.is_deleted='0'

    and d.del_flag='0' and d.dept_type = '2' and d.parent_id >0 and d.`status`='0'
     and d.dept_id = #{deptId}


${params.dataScope}
order by d.parent_id, d.order_num

mapper.update:
update research_diseases
disease_name = #{diseaseName}, dept_id = #{deptId}, is_deleted = #{isDeleted}, create_time = #{createTime}, create_by = #{createBy}, update_time = #{updateTime}, update_by = #{updateBy}, sort_num = #{sortNum},
where 1 = 1
and disease_id = #{diseaseId}
and diseases_groups_id = #{diseasesGroupsId}

mapper.select:
select rd.disease_id,rd.disease_name,ri.research_status,count(ri.id) as num from sys_dept d LEFT JOIN research_diseases rd on rd.dept_id=d.dept_id and rd.is_deleted='0' INNER join research_info ri on ri.disease_type_id=rd.disease_id and ri.del_flag='0' Left join sys_user su on su.user_name=ri.create_by where d.dept_id = #{deptId}
and (ri.id in (select research_id from research_user_role where user_id = #{userId}) or su.user_id = #{userId})
GROUP BY rd.disease_id,rd.disease_name,ri.research_status
